-- Misconception Hunter: persistence for shareable permalinks, per-user session
-- history, and per-user memory. Idempotent -- safe to re-run in the SQL editor.
--
-- Access model: every read/write goes through server-side API routes using the
-- service role key (which bypasses RLS), and those routes derive the user id
-- from the verified Supabase Auth cookie -- never from the request body. RLS is
-- enabled with no policies, which denies the public anon key entirely.
--
-- sessions.id is a short, random, unguessable string generated by the app
-- (see lib/db.ts) so permalinks (/s/<id>) can't be enumerated.

create table if not exists public.sessions (
  id text primary key,
  created_at timestamptz not null default now(),
  topic text,
  transcript jsonb not null,
  summary jsonb not null
);

-- Null for guest sessions; set when a signed-in user finishes a session.
alter table public.sessions
  add column if not exists user_id uuid references auth.users (id) on delete cascade;

create index if not exists sessions_user_id_created_at_idx
  on public.sessions (user_id, created_at desc);

-- What the agent "remembers" about a signed-in student across sessions,
-- derived from each session's structured report. Deleting the auth user (or
-- the "forget everything" button) removes it.
create table if not exists public.memory_items (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  kind text not null check (kind in ('misconception', 'strength', 'topic')),
  label text not null,
  times_seen integer not null default 1,
  last_session_id text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, kind, label)
);

create index if not exists memory_items_user_id_updated_at_idx
  on public.memory_items (user_id, updated_at desc);

alter table public.sessions enable row level security;
alter table public.memory_items enable row level security;

-- service_role's BYPASSRLS only skips row-level policies; it still needs
-- ordinary table-level grants, which tables created via the SQL editor don't
-- get automatically.
grant select, insert, update, delete on public.sessions to service_role;
grant select, insert, update, delete on public.memory_items to service_role;
